-- crashes/similar
-- Possible duplicates for the report form: crashes in the same district within ±2 days,
-- including unreviewed drafts (SPEC 7.1), excluding rejected and merged ones. Newest first, at most 5.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--   $2 = "2026-11-10"
--   $3 = "2026-11-14"
--   $4 = "rejected"
--   $5 = "merged"
--   $6 = 5
--
-- Generated by `pnpm db:queries` from lib/db/queries/reports.ts. Do not edit by hand.

select "id", "slug", "status", "occurred_on", "title_en", "title_np", "place_name_en", "place_name_np", "deaths", "injured_total", (select count(*)::int
from "crash_sources"
where "crash_id" = "id")
from "crashes"
where ("crashes"."district_id" = $1
  and "crashes"."occurred_on" between $2
  and $3
  and "crashes"."status" not in ($4, $5))
order by "crashes"."occurred_on" desc, "crashes"."created_at" desc
limit $6;
